def min_total_distance(citizens: List[List[int]], d: int) -> str:
    def can_reach_all(x_star: int, y_star: int) -> bool:
        return all(abs(x - x_star) + abs(y - y_star) <= d for x, y in citizens)

    xs = sorted([x for x, _ in citizens])
    ys = sorted([y for _, y in citizens])
    m, n = len(xs), len(ys)

    left, right = 0, m - 1
    best_x = xs[left]
    while left < right:
        mid = (left + right) // 2
        if can_reach_all(xs[mid], ys[0]):
            right = mid
            best_x = xs[mid]
        else:
            left = mid + 1

    bottom, top = 0, n - 1
    best_y = ys[bottom]
    while bottom < top:
        mid = (bottom + top) // 2
        if can_reach_all(best_x, ys[mid]):
            top = mid
            best_y = ys[mid]
        else:
            bottom = mid + 1

    if not can_reach_all(best_x, best_y):
        return "impossible"

    total_distance = sum(abs(x - best_x) + abs(y - best_y) for x, y in citizens)
    return str(total_distance)

