    xs = sorted(house[0] for house in houses)
    ys = sorted(house[1] for house in houses)

    left, right = 0, len(xs) - 1
    best_x = xs[left]
    while left <= right:
        mid = (left + right) // 2
        if mid > 0 and mid < len(xs):
            mid_x = (xs[mid-1] + xs[mid]) // 2
        else:
            mid_x = xs[mid]

        top, bottom = 0, len(ys) - 1
        while top <= bottom:
            mid_y = (top + bottom) // 2
            if check(mid_x, ys[mid_y]):
                best_x = mid_x
                break
            elif mid_y > 0 and mid_y < len(ys):
