                    best_x = mid_x
                    break
                elif check(mid_x, ys[mid_y+1]):
                    best_x = mid_x
                    break
            else:
                if check(mid_x, ys[mid]):
                    best_x = mid_x
                    break

        if check(best_x, ys[mid_y]):
            break
        elif mid == 0:
            right = mid - 1
        else:
            left = mid + 1

    if not check(best_x, ys[mid_y]):
        return "impossible"

    return sum(abs(h[0] - best_x) + abs(h[1] - ys[mid_y]) for h in houses)

